mapper.select:
select member_status
from study_member
where study_id = #{studyId}
	and member_id = #{memberId}

mapper.update:
update study_member
set member_status = 'ACTIVE',
joined_at = current_timestamp
where study_id = #{studyId}
and member_id = #{memberId}
and member_status = 'PENDING'

mapper.delete:
    	delete from study_member
    	where study_id = #{studyId}
			and member_id = #{memberId}

mapper.update:
update study_member
set member_status = 'INACTIVE'
where study_id = #{studyId}
and member_id = #{memberId}
